function applyPreset(preset) {  const form = document.createElement('form');  form.method = 'POST';  form.innerHTML = `  <input type="hidden" name="action" value="apply_preset">  <input type="hidden" name="preset" value="${preset}">  `;  document.body.appendChild(form);  form.submit();
}  // Sync color inputs
document.addEventListener('DOMContentLoaded', function() {  const colorInputs = document.querySelectorAll('input[type="color"]');  const textInputs = document.querySelectorAll('input[type="text"][name$="_text"]');  colorInputs.forEach((colorInput, index) => {  const textInput = textInputs[index];  colorInput.addEventListener('change', function() {  if (textInput) {  textInput.value = this.value;  }  });  textInput.addEventListener('change', function() {  if (colorInput && /^#[0-9A-F]{6}$/i.test(this.value)) {  colorInput.value = this.value;  }  });  });
});
</script>  <?php include __DIR__ . '/../partials/footer.php'; ?>  <?php
// Theme configuration functions
function getThemeConfig() {  global $pdo;  try {  $stmt = $pdo->query("SELECT config_key, config_value FROM ui_config WHERE config_category = 'theme'");  $config = [];  while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {  $config[$row['config_key']] = $row['config_value'];  }  return $config;  } catch (Exception $e) {  return [];  }
}  function updateThemeConfig($key, $value) {  global $pdo;  try {  $stmt = $pdo->prepare("INSERT INTO ui_config (config_category, config_key, config_value, updated_at)  VALUES ('theme', ?, ?, CURRENT_TIMESTAMP)  ON DUPLICATE KEY UPDATE config_value = VALUES(config_value), updated_at = CURRENT_TIMESTAMP");  return $stmt->execute([$key, $value]);  } catch (Exception $e) {  error_log("Failed to update theme config: " . $e->getMessage());  return false;  }
}  function applyThemePreset($preset) {  $presets = [  'default' => [  'theme_mode' => 'light',  'primary_color' => '#3b82f6',  'secondary_color' => '#6b7280',  'accent_color' => '#10b981',  'text_size' => 'medium',  'font_family' => 'default',  'sidebar_position' => 'left',  'sidebar_state' => 'expanded'  ],  'corporate' => [  'theme_mode' => 'light',  'primary_color' => '#1e40af',  'secondary_color' => '#374151',  'accent_color' => '#059669',  'text_size' => 'medium',  'font_family' => 'helvetica',  'sidebar_position' => 'left',  'sidebar_state' => 'expanded'  ],  'minimalist' => [  'theme_mode' => 'light',  'primary_color' => '#6b7280',  'secondary_color' => '#9ca3af',  'accent_color' => '#d1d5db',  'text_size' => 'small',  'font_family' => 'arial',  'sidebar_position' => 'left',  'sidebar_state' => 'compact'  ],  'high-contrast' => [  'theme_mode' => 'light',  'primary_color' => '#000000',  'secondary_color' => '#000000',  'accent_color' => '#ffffff',  'text_size' => 'large',  'font_family' => 'default',  'sidebar_position' => 'left',  'sidebar_state' => 'expanded'  ]  ];  if (isset($presets[$preset])) {  foreach ($presets[$preset] as $key => $value) {  updateThemeConfig($key, $value);  }  return true;  }  return false;
}
